#include "darwin_adapter.h"
#include "darwin_observer.h"
#include <stdio.h>
#include <string.h>

static darwin_observer_t observer;
static void help(void){puts("darwin-shell commands:\n  boot | shutdown\n  ps | top\n  sysctl -a\n  kextstat\n  launchctl list | launchctl print <label>\n  service status <label>\n  mach ports | mach send <port> <message>\n  iokit tree\n  dmesg | log show\n  spawn <name>\n  ls [path] | hostname | pwd | whoami | help | exit");}
int main(void){char line[512],a[128],b[256];darwin_observer_init(&observer);puts("Darwin Shell 27.0.0 (simulated user space)");help();for(;;){fputs("darwin% ",stdout);fflush(stdout);if(!fgets(line,sizeof(line),stdin))break;if(sscanf(line,"%127s %255s",a,b)<1)continue;if(!strcmp(a,"exit")||!strcmp(a,"quit"))break;if(!strcmp(a,"help")){help();continue;}if(!strcmp(a,"boot")){darwin_observer_boot(&observer);puts("boot complete");continue;}if(!strcmp(a,"shutdown")){darwin_observer_shutdown(&observer);puts("shutdown requested");continue;}if(!strcmp(a,"ps")){darwin_print_processes(&observer,0);continue;}if(!strcmp(a,"top")){darwin_print_processes(&observer,1);continue;}if(!strcmp(a,"sysctl")){puts("kern.ostype: Darwin\nkern.osrelease: 27.0.0\nkern.ipc.mach_ports: 64\nkern.processes.virtual: 32");continue;}if(!strcmp(a,"kextstat")){puts("Index Refs Address Size Name\n  0   1   0x0  0x1000 com.apple.kernel\n  1   1   0x0  0x0800 com.apple.iokit");continue;}if(!strcmp(a,"launchctl")){darwin_print_services();continue;}if(!strcmp(a,"service")&&strstr(line,"status")){printf("%s: %s\n",b,darwin_service_status(b)==0?"running":"not found");continue;}if(!strcmp(a,"mach")){if(strstr(line,"ports"))darwin_print_ports(&observer);else if(strstr(line,"send")){int port=0;sscanf(line,"mach send %d",&port);darwin_send_message(&observer,port,"shell message");puts("message sent");}continue;}if(!strcmp(a,"iokit")){darwin_print_devices(&observer);continue;}if(!strcmp(a,"dmesg")||!strcmp(a,"log")){darwin_print_logs(&observer);continue;}if(!strcmp(a,"spawn")){printf("spawned pid %d\n",darwin_spawn(&observer,b));continue;}if(!strcmp(a,"hostname")){puts(darwin_adapter_hostname());continue;}if(!strcmp(a,"pwd")){puts(darwin_adapter_cwd());continue;}if(!strcmp(a,"whoami")){puts("root");continue;}if(!strcmp(a,"ls")){darwin_adapter_list(sscanf(line,"ls %255s",b)==1?b:".");continue;}puts("darwin-shell: command not found");}return 0;}
